import base64
import json

# Read and encode charts as base64
def encode_image(path):
    with open(path, 'rb') as f:
        return base64.b64encode(f.read()).decode('utf-8')

charts = {
    'temporal_trends': encode_image('/app/output/charts/temporal_trends.png'),
    'correlation': encode_image('/app/output/charts/correlation.png'),
    'regional_comparison': encode_image('/app/output/charts/regional_comparison.png'),
    'subsidy_analysis': encode_image('/app/output/charts/subsidy_analysis.png'),
    'income_analysis': encode_image('/app/output/charts/income_analysis.png'),
    'price_distribution': encode_image('/app/output/charts/price_distribution.png')
}

# Read stats
with open('/app/output/computed_stats.json', 'r') as f:
    stats = json.load(f)

# Generate HTML report
html = f'''<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
